import os,json,urllib.request,urllib.error,sys,datetime
BASE=os.environ['MCPJAM_API_URL'].rstrip('/')
def call(method,path,body=None,label=None):
 data=None if body is None else json.dumps(body).encode()
 req=urllib.request.Request(BASE+path,data=data,method=method,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'})
 try:
  with urllib.request.urlopen(req,timeout=25) as r: status=r.status; raw=r.read().decode()
 except urllib.error.HTTPError as e: status=e.code;raw=e.read().decode()
 try: result=json.loads(raw)
 except ValueError: result={'raw':raw}
 entry={'method':method,'path':path,'status':status,'response':result}
 with open('/workspace/validation/requests.jsonl','a') as f:f.write(json.dumps(entry)+'\n')
 if label:json.dump(entry,open('/workspace/validation/'+label+'.json','w'),indent=2)
 print(json.dumps(entry));return status,result
if __name__=='__main__':call(sys.argv[1],sys.argv[2],json.loads(sys.argv[3]) if len(sys.argv)>3 else None,sys.argv[4] if len(sys.argv)>4 else None)
